package vn.covie.inventory.api;
import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import vn.covie.inventory.api.dto.*; import vn.covie.inventory.application.*;
@RestController @RequestMapping("/api/v1/merchants/{merchantId}/inventory") public class MerchantInventoryController{private final InventoryQueryService query;private final InventoryAdjustmentService adjustments;private final InventoryBulkService bulk;public MerchantInventoryController(InventoryQueryService query,InventoryAdjustmentService adjustments,InventoryBulkService bulk){this.query=query;this.adjustments=adjustments;this.bulk=bulk;}@GetMapping public List<InventoryItemResponse> list(@PathVariable UUID merchantId){return query.list(merchantId);}@PostMapping("/{locationVariantId}/set-stock")public ResponseEntity<InventoryCommandResult> setStock(@PathVariable UUID merchantId,@PathVariable UUID locationVariantId,@RequestHeader("Idempotency-Key")String key,@RequestBody SetStockRequest req){return ResponseEntity.ok(adjustments.setStock(merchantId,locationVariantId,key,req));}@PostMapping("/{locationVariantId}/stock-in")public ResponseEntity<InventoryCommandResult> stockIn(@PathVariable UUID merchantId,@PathVariable UUID locationVariantId,@RequestHeader("Idempotency-Key")String key,@RequestBody StockMovementRequest req){return ResponseEntity.ok(adjustments.stockIn(merchantId,locationVariantId,key,req));}@PostMapping("/{locationVariantId}/stock-out")public ResponseEntity<InventoryCommandResult> stockOut(@PathVariable UUID merchantId,@PathVariable UUID locationVariantId,@RequestHeader("Idempotency-Key")String key,@RequestBody StockMovementRequest req){return ResponseEntity.ok(adjustments.stockOut(merchantId,locationVariantId,key,req));}@PostMapping("/bulk-set-stock")public ResponseEntity<BulkSetStockResult> bulkSet(@PathVariable UUID merchantId,@RequestHeader("Idempotency-Key")String key,@RequestBody BulkSetStockRequest req){return ResponseEntity.ok(bulk.setStock(merchantId,key,req));}}
